IODPRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice Read-only ABI for the redesigned 0.7 generation; incompatible with legacy 0.7.
interface IODPRegistry {
    struct CreatorRecord {
        string  creatorId;    // "C-482-930-174-005"
        address wallet;
        bytes1  typePrefix;   // "C", "B", "P", or "M" — stored as bytes1 for gas efficiency
        uint256 timestamp;
    }

    struct PassportHeaderView {
        string  passportId;
        uint8   contractVersion;
        address creator;
        string  creatorId;
        uint32  year;
        uint8   month;
        string  title;
        string  authorName;
        string  shortDescription;
        string  domain;
        string  objectType;
    }

    struct PassportClassificationView {
        uint8   contentClass;
        uint8   lifecycleStatus;
        uint8   aiStatus;
        uint8   verificationMethod;
        uint8   editionModel;
        uint256 timestamp;
        bool    revoked;
        uint256 revokedAt;
        bytes32 revocationReasonHash;
    }

    struct PassportMediaView {
        bytes32 dataHash;
        bytes32 imageHash;
        bytes32 fileHash;
        bytes32 anchorsHash;
        uint32  anchorTypesMask;
        bytes32 editionCommitment;
    }
    function getCreator(string calldata id) external view returns (CreatorRecord memory);
    function getCreatorByWallet(address wallet) external view returns (string memory);
    function getPassportHeader(string calldata id) external view returns (PassportHeaderView memory);
    function getPassportMedia(string calldata id) external view returns (PassportMediaView memory);
    function getPassportClassification(string calldata id) external view returns (PassportClassificationView memory);
    function passportExists(string calldata id) external view returns (bool);
}

ODPAuthorAttestation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ODPSatellite.sol";

import "./ODPErrors.sol";

/**
 * Optional satellite: EIP-712 author attestation for a passport (SPEC §8, planned option B).
 *
 * Binds a *separate* author key to a passport's integrity anchor (`dataHash`) and issuer
 * profile (`creatorId`), independently of the wallet that sent the mint transaction. This
 * gives verifiers two independent trust signals: "this wallet minted it" and "this author
 * key signed exactly these bytes". This is independent only if the verifier already trusts
 * that author key through a separate channel. An issuer can choose its own key and occupy
 * the one-shot slot; the signature alone does not establish author identity.
 *
 * Deploy after `ObjectDigitalPassport`; the constructor pins one registry address.
 * Keeps the main registry bytecode untouched (EIP-170) — no re-deploy of the canonical
 * registry is required to adopt this feature.
 *
 * Attestation is one-shot and immutable per passport, matching the immutability class of
 * the on-chain card: the signer can withdraw consent without erasing history. Independent author
 * declarations and their replacements use ODPStatementJournal.
 */

contract ODPAuthorAttestation is ODPSatellite {

    /// @dev EIP-712 domain. `verifyingContract` is this satellite, so a signature made for
    ///      one anchor contract is not replayable against another.
    bytes32 private constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant NAME_HASH = keccak256("Object Digital Passport");
    bytes32 private constant VERSION_HASH = keccak256("1");

    /// @dev The signed struct binds the passport identity, the exact document bytes
    ///      (`dataHash`), the issuing profile, and the declared author key together.
    bytes32 private constant ATTESTATION_TYPEHASH =
        keccak256("AuthorAttestation(string passportId,bytes32 dataHash,string creatorId,address authorSigner)");

    /// @dev Cached for the deployment chain; recomputed if `block.chainid` changes (fork safety).
    bytes32 private immutable _cachedDomainSeparator;
    uint256 private immutable _cachedChainId;

    struct AuthorAttestation {
        address authorSigner;
        bytes32 dataHash;
        string  creatorId;
        uint256 timestamp;
        address submittedBy;
    }

    mapping(string => AuthorAttestation) private _attestation;
    mapping(string => uint256) public authorWithdrawalAt;
    mapping(string => bytes32) public authorWithdrawalReason;
    event AuthorAttestationWithdrawn(string indexed passportId, string passportIdText, address indexed authorSigner, bytes32 reasonHash, uint256 timestamp);
    error InvalidAuthorWithdrawal();

    /// @notice Signer can withdraw consent independently of issuer authorization.
    /// Historical getAuthorAttestation remains true; readers MUST check withdrawal state.
    function withdrawAuthorAttestation(string calldata passportId, bytes32 reasonHash) external {
        if (_attestation[passportId].authorSigner != msg.sender || authorWithdrawalAt[passportId] != 0 || reasonHash == bytes32(0)) revert InvalidAuthorWithdrawal();
        authorWithdrawalAt[passportId] = block.timestamp;
        authorWithdrawalReason[passportId] = reasonHash;
        emit AuthorAttestationWithdrawn(passportId, passportId, msg.sender, reasonHash, block.timestamp);
    }

    event AuthorAttested(
        string  indexed passportId,
        string passportIdText,
        string creatorIdText,
        address indexed authorSigner,
        string  indexed creatorId,
        bytes32 dataHash,
        address submittedBy,
        uint256 timestamp
    );

    constructor(address registry_) ODPSatellite(registry_) {
        _cachedChainId = block.chainid;
        _cachedDomainSeparator = _buildDomainSeparator();
    }

    function _buildDomainSeparator() private view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, NAME_HASH, VERSION_HASH, block.chainid, address(this)));
    }

    /// @notice EIP-712 domain separator for this satellite on the current chain.
    function domainSeparator() public view returns (bytes32) {
        if (block.chainid == _cachedChainId) return _cachedDomainSeparator;
        return _buildDomainSeparator();
    }

    /**
     * @notice EIP-712 digest the author key must sign. Clients SHOULD compute this locally
     *         (e.g. `signTypedData`) and MAY call this to cross-check.
     */
    function hashAuthorAttestation(
        string calldata passportId,
        bytes32 dataHash,
        string calldata creatorId,
        address authorSigner
    ) external view returns (bytes32) {
        return _hashAuthorAttestation(passportId, dataHash, creatorId, authorSigner);
    }

    function _hashAuthorAttestation(
        string memory passportId,
        bytes32 dataHash,
        string memory creatorId,
        address authorSigner
    ) private view returns (bytes32) {
        bytes32 structHash = keccak256(
            abi.encode(
                ATTESTATION_TYPEHASH,
                keccak256(bytes(passportId)),
                dataHash,
                keccak256(bytes(creatorId)),
                authorSigner
            )
        );
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), structHash));
    }

    /**
     * @notice Record an author attestation for `passportId`.
     * @dev Caller must be the passport's `creator` — this prevents a third party
     *      from squatting the single attestation slot with a key of their own. The signature
     *      itself must come from `authorSigner` over the passport's *current on-chain*
     *      `dataHash` and `creatorId`, so the binding cannot be pointed at other bytes.
     */
    function attestAuthor(
        string calldata passportId,
        address authorSigner,
        bytes calldata signature
    ) external {
        if (authorSigner == address(0)) revert EC(110);
        if (_attestation[passportId].authorSigner != address(0)) revert EC(111);

        // Reverts if the passport does not exist on the paired registry.
        IODPRegistry.PassportHeaderView memory h = odpRegistry.getPassportHeader(passportId);
        if (!(msg.sender == h.creator)) revert EC(112);
        if (odpRegistry.getPassportClassification(passportId).revoked) revert EC(11);

        _registered();
        bytes32 dataHash = odpRegistry.getPassportMedia(passportId).dataHash;
        bytes32 digest = _hashAuthorAttestation(passportId, dataHash, h.creatorId, authorSigner);
        if (_recover(digest, signature) != authorSigner) revert EC(115);

        _attestation[passportId] = AuthorAttestation({
            authorSigner: authorSigner,
            dataHash: dataHash,
            creatorId: h.creatorId,
            timestamp: block.timestamp,
            submittedBy: msg.sender
        });

        emit AuthorAttested(passportId, passportId, h.creatorId, authorSigner, h.creatorId, dataHash, msg.sender, block.timestamp);
    }

    /**
     * @notice Read the attestation for a passport.
     * @return attested   false when no author key has been bound.
     * @return authorSigner the attesting key.
     * @return dataHash   the `dataHash` that was signed — verifiers MUST compare this to the
     *                    passport's current on-chain `dataHash` before trusting the binding.
     * @return creatorId  the issuing profile the signature was bound to.
     * @return timestamp  when the attestation was recorded.
     */
    function getAuthorAttestation(string calldata passportId)
        external
        view
        returns (
            bool attested,
            address authorSigner,
            bytes32 dataHash,
            string memory creatorId,
            uint256 timestamp
        )
    {
        AuthorAttestation storage a = _attestation[passportId];
        if (a.authorSigner == address(0)) {
            return (false, address(0), bytes32(0), "", 0);
        }
        return (true, a.authorSigner, a.dataHash, a.creatorId, a.timestamp);
    }

    /// @dev Minimal ECDSA recover with EIP-2 low-s and valid-v enforcement (no malleable pairs).
    function _recover(bytes32 digest, bytes calldata signature) private pure returns (address) {
        if (signature.length != 65) revert EC(113);
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 32))
            v := byte(0, calldataload(add(signature.offset, 64)))
        }
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert EC(114);
        if (v != 27 && v != 28) revert EC(114);
        address signer = ecrecover(digest, v, r, s);
        if (signer == address(0)) revert EC(115);
        return signer;
    }
}

ODPEditionUnits.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ODPSatellite.sol";

import "./ODPErrors.sol";

contract ODPEditionUnits is ODPSatellite {
    bytes1 private constant TYPE_B = "B";

    /// Absolute proof-length bound; canonical trees under the count cap need at most 20 levels.
    uint256 private constant MAX_PROOF = 32;

    struct Edition {
        bytes32 merkleRoot;
        uint32 unitCount;
        bool open;
        bytes32 editionNonce;
        // SPEC §20.7 — the key an offline reader checks a signed outer label against.
        // address(0) = this edition prints plain labels. Immutable with the edition.
        address labelSigner;
    }

    struct Activation {
        uint64 timestamp;
        address unitAddress;
    }

    mapping(string => Edition) private _editions;
    mapping(address => mapping(bytes32 => string)) private _editionPassportByNonce;
    error EditionCommitmentMismatch();
    error EditionNonceAlreadyUsed(string passportId);
    mapping(bytes32 => Activation) private _activations;

    event EditionOpened(
        string editionPassportId,
        bytes32 merkleRoot,
        uint32 unitCount,
        address labelSigner,
        bytes32 editionNonce,
        address indexed issuer
    );
    event UnitActivated(string editionPassportId, uint32 indexed unitIndex, address indexed unitAddress, uint256 timestamp);

    constructor(address registry_) ODPSatellite(registry_) {
    }

    // ─── Issuer surface ───────────────────────────────────────────────────────

    function openEdition(
        string calldata editionPassportId,
        bytes32 merkleRoot,
        uint32 unitCount,
        address labelSigner,
        bytes32 editionNonce
    ) external {
        if (_editions[editionPassportId].open) revert EC(119);
        if (!(merkleRoot != bytes32(0))) revert EC(118);
        if (!(unitCount > 0 && unitCount <= 1_048_576)) revert EC(122);

        IODPRegistry.PassportHeaderView memory h = odpRegistry.getPassportHeader(editionPassportId);
        if (!(msg.sender == h.creator)) revert EC(120);
        if (!(odpRegistry.getCreator(h.creatorId).typePrefix == TYPE_B)) revert EC(121);

        _registered();
        IODPRegistry.PassportClassificationView memory c = odpRegistry.getPassportClassification(editionPassportId);
        if (c.revoked) revert EC(11);
        if (c.editionModel != 2 && c.editionModel != 3) revert EC(122);
        if ((odpRegistry.getPassportMedia(editionPassportId).anchorTypesMask & 4096) == 0) revert EC(105);
        if (editionNonce == bytes32(0)) revert EC(141);
        if (odpRegistry.getPassportMedia(editionPassportId).editionCommitment !=
            commitmentFor(h.creator, merkleRoot, unitCount, labelSigner, editionNonce)) {
            revert EditionCommitmentMismatch();
        }
        string storage prior = _editionPassportByNonce[h.creator][editionNonce];
        if (bytes(prior).length != 0) revert EditionNonceAlreadyUsed(prior);
        _editionPassportByNonce[h.creator][editionNonce] = editionPassportId;
        _editions[editionPassportId] = Edition({
            merkleRoot: merkleRoot,
            unitCount: unitCount,
            open: true,
            editionNonce: editionNonce,
            labelSigner: labelSigner
        });

        emit EditionOpened(editionPassportId, merkleRoot, unitCount, labelSigner, editionNonce, msg.sender);
    }

    /// @notice Exact typed commitment to prepare before mint. No passportId circular dependency.
    /// @dev Domain fixes unit derivation v2, SHA256/indexed-address leaves and duplicate-odd tree rules.
    function commitmentFor(address issuer, bytes32 root, uint32 count, address labelSigner, bytes32 nonce)
        public view returns (bytes32)
    {
        return keccak256(abi.encode("ODP-EDITION-COMMITMENT-0.7", block.chainid,
            address(odpRegistry), issuer, address(this), nonce, root, count, labelSigner));
    }

    function editionPassportByNonce(address issuer, bytes32 nonce) external view returns (string memory) {
        return _editionPassportByNonce[issuer][nonce];
    }

    // ─── Activation ───────────────────────────────────────────────────────────

    function activate(
        string calldata editionPassportId,
        uint32 unitIndex,
        bytes32[] calldata proof,
        bytes calldata signature
    ) external {
        Edition storage ed = _editions[editionPassportId];
        if (!ed.open) revert EC(118);
        if (odpRegistry.getPassportClassification(editionPassportId).revoked) revert EC(11);
        if (!(unitIndex < ed.unitCount)) revert EC(122);

        bytes32 slot = _slot(editionPassportId, unitIndex);
        if (_activations[slot].timestamp != 0) revert EC(124);

        address unitAddress = _recoverSigner(activationPayloadHash(editionPassportId, unitIndex), signature);
        if (!_proves(ed.merkleRoot, proof, unitIndex, unitAddress)) revert EC(123);

        _activations[slot] = Activation({ timestamp: uint64(block.timestamp), unitAddress: unitAddress });

        emit UnitActivated(editionPassportId, unitIndex, unitAddress, block.timestamp);
    }

    // ─── Reads ────────────────────────────────────────────────────────────────

    function getEdition(string calldata editionPassportId)
        external view returns (bytes32 merkleRoot, uint32 unitCount, bool open, bytes32 editionNonce, address labelSigner)
    {
        Edition storage ed = _editions[editionPassportId];
        return (ed.merkleRoot, ed.unitCount, ed.open, ed.editionNonce, ed.labelSigner);
    }

    function labelPayloadHash(string calldata editionPassportId, uint32 unitIndex)
        public view returns (bytes32)
    {
        Edition storage ed = _editions[editionPassportId];
        return keccak256(
            abi.encodePacked(
                "ODP-UNIT-LABEL-v1",
                uint256(block.chainid),
                address(this),
                editionPassportId,
                unitIndex,
                ed.merkleRoot
            )
        );
    }

    /// Returns `(0, address(0))` when the unit has never been activated.
    function getActivation(string calldata editionPassportId, uint32 unitIndex)
        external view returns (uint256 timestamp, address unitAddress)
    {
        Activation storage a = _activations[_slot(editionPassportId, unitIndex)];
        return (a.timestamp, a.unitAddress);
    }

    function isActivated(string calldata editionPassportId, uint32 unitIndex) external view returns (bool) {
        return _activations[_slot(editionPassportId, unitIndex)].timestamp != 0;
    }

    /// The message a unit key signs (§20.9), exposed so wallets and tools agree byte-for-byte.
    function activationPayloadHash(string calldata editionPassportId, uint32 unitIndex)
        public view returns (bytes32)
    {
        return keccak256(
            abi.encodePacked(
                "ODP-UNIT-ACTIVATE-v1",
                uint256(block.chainid),
                address(this),
                editionPassportId,
                unitIndex
            )
        );
    }

    /// SPEC §20.3 leaf: `SHA-256( uint32be(index) || address20 )`.
    function unitLeaf(uint32 unitIndex, address unitAddress) public pure returns (bytes32) {
        return sha256(abi.encodePacked(unitIndex, unitAddress));
    }

    // ─── Internals ────────────────────────────────────────────────────────────

    function _slot(string calldata editionPassportId, uint32 unitIndex) private pure returns (bytes32) {
        return keccak256(abi.encode(editionPassportId, unitIndex));
    }

    function _recoverSigner(bytes32 payloadHash, bytes calldata signature) private pure returns (address) {
        if (!(signature.length == 65)) revert EC(125);
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 32))
            v := byte(0, calldataload(add(signature.offset, 64)))
        }
        // EIP-2 low-s; rejects the trivially malleable half of the curve.
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert EC(125);
        if (v < 27) v += 27;
        if (!(v == 27 || v == 28)) revert EC(125);

        bytes32 digest = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", payloadHash));
        address signer = ecrecover(digest, v, r, s);
        if (!(signer != address(0))) revert EC(125);
        return signer;
    }

    function _proves(
        bytes32 root,
        bytes32[] calldata proof,
        uint32 unitIndex,
        address unitAddress
    ) private pure returns (bool) {
        if (proof.length > MAX_PROOF) revert EC(127);
        bytes32 node = unitLeaf(unitIndex, unitAddress);
        uint256 idx = unitIndex;
        for (uint256 i = 0; i < proof.length; i++) {
            node = (idx & 1 == 0)
                ? sha256(abi.encodePacked(node, proof[i]))
                : sha256(abi.encodePacked(proof[i], node));
            idx >>= 1;
        }
        return node == root;
    }
}

