ODPHosting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ODPSatellite.sol";

/// @notice Replaceable transport locations. Integrity always comes from the core's hashes.
/// @dev Publishing delegation is separate from mint delegation. Profile registration is permanent; there is no stop switch.
contract ODPHosting is ODPSatellite {
    struct Locations { string dataUrl; string imageUrl; uint256 updatedAt; }
    struct Delegation { address agent; uint256 expiresAt; }
    mapping(string => Locations) private _locations;
    mapping(address => Delegation) private _delegations;
    event LocationsUpdated(string indexed passportId, string passportIdText,
        string dataUrl, string imageUrl, address indexed updatedBy, uint256 timestamp);
    event PublishingDelegated(address indexed creator, address indexed agent, uint256 expiresAt);
    constructor(address registry) ODPSatellite(registry) {}
    function delegatePublishing(address agent, uint256 expiresAt) external {
        _registered();
        if (agent == address(0)) revert EC(21);
        if (expiresAt <= block.timestamp) revert EC(20);
        _delegations[msg.sender] = Delegation(agent, expiresAt);
        emit PublishingDelegated(msg.sender, agent, expiresAt);
    }
    function revokePublishing() external {
        _registered();
        delete _delegations[msg.sender];
        emit PublishingDelegated(msg.sender, address(0), 0);
    }
    function getPublishingDelegation(address creator) external view returns (Delegation memory) {
        return _delegations[creator];
    }
    function updateLocations(string calldata id, string calldata dataUrl, string calldata imageUrl) external {
        IODPRegistry.PassportHeaderView memory h = odpRegistry.getPassportHeader(id);
        Delegation storage d = _delegations[h.creator];
        if (msg.sender != h.creator && (msg.sender != d.agent || block.timestamp >= d.expiresAt)) revert EC(137);
        if (bytes(dataUrl).length > 512 || bytes(imageUrl).length > 512) revert EC(138);
        _locations[id] = Locations(dataUrl, imageUrl, block.timestamp);
        emit LocationsUpdated(id, id, dataUrl, imageUrl, msg.sender, block.timestamp);
    }
    function getLocations(string calldata id) external view returns (Locations memory) { return _locations[id]; }
}

ODPPassportConcerns.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ODPSatellite.sol";

/// @notice Independent statements, never an authenticity verdict. One active episode per pair.
contract ODPPassportConcerns is ODPSatellite {
    struct Concern {
        string raisedBy;
        bytes32 reasonHash;
        string reasonUrl;
        uint64 raisedAt;
        uint64 withdrawnAt;
    }
    mapping(bytes32 => Concern) private _concerns;
    mapping(string => string[]) private _raisersOf;
    mapping(string => string[]) private _raisedOn;
    mapping(string => uint256) public activeConcernCount;
    event ConcernRaised(string indexed passportId, string indexed raisedBy,
        string passportIdText, string raisedByText, bytes32 reasonHash, string reasonUrl, uint256 timestamp);
    event ConcernWithdrawn(string indexed passportId, string indexed raisedBy,
        string passportIdText, string raisedByText, uint256 timestamp);
    constructor(address registry) ODPSatellite(registry) {}
    function raiseConcern(string calldata passportId, bytes32 reasonHash, string calldata reasonUrl) external {
        string memory id = _institution();
        if (!odpRegistry.passportExists(passportId)) revert EC(12);
        if (reasonHash == bytes32(0)) revert EC(133);
        if (bytes(reasonUrl).length > 512) revert EC(134);
        bytes32 key = keccak256(abi.encode(passportId, id));
        Concern storage c = _concerns[key];
        bool exists = bytes(c.raisedBy).length != 0;
        if (exists && c.withdrawnAt == 0) revert EC(135);
        if (!exists) {
            _raisersOf[passportId].push(id);
            _raisedOn[id].push(passportId);
        }
        _concerns[key] = Concern(id, reasonHash, reasonUrl, uint64(block.timestamp), 0);
        activeConcernCount[passportId]++;
        emit ConcernRaised(passportId, id, passportId, id, reasonHash, reasonUrl, block.timestamp);
    }
    function withdrawConcern(string calldata passportId) external {
        // Cleanup of an existing own statement requires its original author.
        string memory id = _registered();
        Concern storage c = _concerns[keccak256(abi.encode(passportId, id))];
        if (bytes(c.raisedBy).length == 0 || c.withdrawnAt != 0) revert EC(136);
        c.withdrawnAt = uint64(block.timestamp);
        activeConcernCount[passportId]--;
        emit ConcernWithdrawn(passportId, id, passportId, id, block.timestamp);
    }
    function getConcern(string calldata passportId, string calldata raisedBy) external view returns (Concern memory) {
        return _concerns[keccak256(abi.encode(passportId, raisedBy))];
    }
    function getConcernRaisersPaged(string calldata id, uint256 offset, uint256 limit)
        external view returns (string[] memory, uint256) { return _page(_raisersOf[id], offset, limit); }
    function getConcernsByRaiserPaged(string calldata id, uint256 offset, uint256 limit)
        external view returns (string[] memory, uint256) { return _page(_raisedOn[id], offset, limit); }
}

ODPPassportLib.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./ODPErrors.sol";
import {
    ODPAnchorBits,
    PassportCoreMintInputs,
    PassportMintInputs
} from "./ODPPassportTypes.sol";

/// @dev Internal-only validation and formatting: no linked deployment or external calls.
library ODPPassportLib {
    uint8 private constant CONTENT_CLASS_STATIC = 1;
    uint8 private constant CONTENT_CLASS_EXECUTABLE = 6;
    uint8 private constant STATUS_CONCEPT = 1;
    uint8 private constant STATUS_ARCHIVED = 4;
    uint8 private constant AI_STATUS_NONE = 1;
    uint8 private constant AI_STATUS_GENERATED = 3;
    uint8 private constant VERIFY_SELF = 1;
    uint8 private constant VERIFY_HYBRID = 5;
    uint8 private constant EDITION_UNIQUE = 1;
    uint8 private constant EDITION_DYNAMIC = 4;

    function validateContentClass(uint8 contentClass) internal pure {
        if (!(contentClass >= CONTENT_CLASS_STATIC && contentClass <= CONTENT_CLASS_EXECUTABLE)) revert EC(84);
    }

    function validateLifecycleStatus(uint8 lifecycleStatus) internal pure {
        if (!(lifecycleStatus >= STATUS_CONCEPT && lifecycleStatus <= STATUS_ARCHIVED)) revert EC(85);
    }

    function validateAiStatus(uint8 aiStatus) internal pure {
        if (!(aiStatus >= AI_STATUS_NONE && aiStatus <= AI_STATUS_GENERATED)) revert EC(86);
    }

    function validateVerificationMethod(uint8 verificationMethod) internal pure {
        if (!(verificationMethod >= VERIFY_SELF && verificationMethod <= VERIFY_HYBRID)) revert EC(87);
    }

    function validateEditionModel(uint8 editionModel) internal pure {
        if (!(editionModel >= EDITION_UNIQUE && editionModel <= EDITION_DYNAMIC)) revert EC(88);
    }

    /// @dev Immutable on-chain card: no edit path exists after mint (typo = revoke + re-mint).
    function validatePassportCore(PassportCoreMintInputs memory core) internal pure {
        if (!(core.year > 0)) revert EC(9);
        if (!(core.month >= 1 && core.month <= 12)) revert EC(8);
        if (!(bytes(core.title).length > 0)) revert EC(91);
        if (!(bytes(core.title).length <= 128)) revert EC(92);
        if (!(bytes(core.authorName).length > 0)) revert EC(99);
        if (!(bytes(core.authorName).length <= 128)) revert EC(100);
        if (!(bytes(core.shortDescription).length > 0)) revert EC(101);
        if (!(bytes(core.shortDescription).length <= 256)) revert EC(102);
        if (!(bytes(core.domain).length <= 128)) revert EC(93);
        validateContentClass(core.contentClass);
        validateLifecycleStatus(core.lifecycleStatus);
        validateAiStatus(core.aiStatus);
        validateVerificationMethod(core.verificationMethod);
        validateEditionModel(core.editionModel);
    }

    function validateCommonMintInputs(PassportMintInputs memory m) internal pure {
        validatePassportCore(m.core);
        if (!(m.dataHash != bytes32(0))) revert EC(30);
        if (!(m.anchorsHash != bytes32(0))) revert EC(103);
        if (!(m.anchorTypesMask != 0)) revert EC(104);
    }

    function requireAnchorBits(uint32 mask, uint32 required) internal pure {
        if (!((mask & required) == required)) revert EC(105);
    }

    function validatePhysicalMintInputs(PassportMintInputs memory m) internal pure {
        validateCommonMintInputs(m);
        if (!(m.fileHash == bytes32(0))) revert EC(106);
        if (!(m.imageHash != bytes32(0))) revert EC(107);
        requireAnchorBits(m.anchorTypesMask, ODPAnchorBits.PHYSICAL_REQUIRED);
    }

    function validateDigitalMintInputs(PassportMintInputs memory m) internal pure {
        validateCommonMintInputs(m);
        if (!(m.fileHash != bytes32(0))) revert EC(29);
        requireAnchorBits(m.anchorTypesMask, ODPAnchorBits.DIGITAL_REQUIRED);
    }

    function validateMixedMintInputs(PassportMintInputs memory m) internal pure {
        validateCommonMintInputs(m);
        if (!(m.fileHash != bytes32(0))) revert EC(29);
        if (!(m.imageHash != bytes32(0))) revert EC(107);
        requireAnchorBits(m.anchorTypesMask, ODPAnchorBits.PHYSICAL_REQUIRED | ODPAnchorBits.DIGITAL_REQUIRED);
    }

    // ─── UTC calendar (ODP-ID / PRF-ID must match mint/proof block month in UTC) ─

    function _isLeapYear(uint256 y) private pure returns (bool) {
        return ((y % 4 == 0) && (y % 100 != 0)) || (y % 400 == 0);
    }

    function _daysInYear(uint256 y) private pure returns (uint256) {
        return _isLeapYear(y) ? 366 : 365;
    }

    function _daysInMonth(uint256 m, uint256 y) private pure returns (uint256) {
        if (m == 1 || m == 3 || m == 5 || m == 7 || m == 8 || m == 10 || m == 12) return 31;
        if (m == 4 || m == 6 || m == 9 || m == 11) return 30;
        return _isLeapYear(y) ? 29 : 28;
    }

    /// @dev Gregorian UTC: Unix `ts` seconds since 1970-01-01 00:00:00 UTC.
    /// @notice Reverts EC(83) if `ts` is outside a supported range (internal calendar loop bound).
    function utcYearMonthFromTimestamp(uint256 ts) internal pure returns (uint32 year, uint8 month) {
        uint256 dayCount = ts / 86400;
        uint256 y = 1970;
        for (uint256 i = 0; i < 600; i++) {
            uint256 diy = _daysInYear(y);
            if (dayCount < diy) {
                break;
            }
            dayCount -= diy;
            y++;
        }
        if (dayCount >= _daysInYear(y)) revert EC(83);

        uint256 m = 1;
        uint256 rem = dayCount;
        bool found = false;
        for (uint256 mi = 1; mi <= 12; mi++) {
            uint256 dim = _daysInMonth(mi, y);
            if (rem < dim) {
                m = mi;
                found = true;
                break;
            }
            rem -= dim;
        }
        if (!found) revert EC(83);

        year = uint32(y);
        month = uint8(m);
    }

    // ─── Internal string formatters ─

    function yearToString(uint32 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint32 temp = v;
        uint256 len = 0;
        while (temp > 0) {
            len++;
            temp /= 10;
        }
        bytes memory b = new bytes(len);
        for (uint256 i = len; i > 0; i--) {
            b[i - 1] = bytes1(uint8(48 + v % 10));
            v /= 10;
        }
        return string(b);
    }

    function monthToString(uint8 v) internal pure returns (string memory) {
        bytes memory b = new bytes(2);
        b[1] = bytes1(uint8(48 + v % 10));
        b[0] = bytes1(uint8(48 + (v / 10) % 10));
        return string(b);
    }

    function pad8(uint32 v) internal pure returns (string memory) {
        bytes memory b = new bytes(8);
        for (uint256 i = 8; i > 0; i--) {
            b[i - 1] = bytes1(uint8(48 + v % 10));
            v /= 10;
        }
        return string(b);
    }

    function formatOdpPassportId(uint32 year, uint8 month, uint32 n) internal pure returns (string memory) {
        return string(abi.encodePacked("ODP-", yearToString(year), "-", monthToString(month), "-", pad9(n)));
    }

    function formatPrfId(uint32 year, uint8 month, uint32 n) internal pure returns (string memory) {
        return string(abi.encodePacked("PRF-", yearToString(year), "-", monthToString(month), "-", pad8(n)));
    }

    function pad9(uint32 v) internal pure returns (string memory) {
        bytes memory b = new bytes(9);
        for (uint256 i = 9; i > 0; i--) {
            b[i - 1] = bytes1(uint8(48 + v % 10));
            v /= 10;
        }
        return string(b);
    }

    function pad3(uint32 v) internal pure returns (string memory) {
        bytes memory b = new bytes(3);
        b[2] = bytes1(uint8(48 + v % 10));
        b[1] = bytes1(uint8(48 + (v / 10) % 10));
        b[0] = bytes1(uint8(48 + (v / 100) % 10));
        return string(b);
    }

    /// @dev "C-482-930-174-005" style creator id body from type prefix and number.
    function buildCreatorId(bytes1 typePrefix, uint64 number) internal pure returns (string memory) {
        return string(
            abi.encodePacked(
                string(abi.encodePacked(typePrefix)),
                "-",
                pad3(uint32(number / 1_000_000_000)),
                "-",
                pad3(uint32((number / 1_000_000) % 1_000)),
                "-",
                pad3(uint32((number / 1_000) % 1_000)),
                "-",
                pad3(uint32(number % 1_000))
            )
        );
    }
}

ODPPassportProofRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ODPSatellite.sol";

import "./ODPErrors.sol";
import "./ODPPassportLib.sol";

/**
 * Satellite: passport-bound institutional attestations (P / M profiles).
 * Deploy after `ObjectDigitalPassport`; constructor takes the registry address.
 *
 * Attestation model (SPEC.md §4): an attestation states
 * "this passport/object has been examined" as a whole — no per-anchor granularity.
 * `documentHash` optionally anchors a signed expertise document (PDF, report);
 * details of what exactly was examined belong in that document.
 */

contract ODPPassportProofRegistry is ODPSatellite {

    // Must match the registry this satellite is wired to (SPEC §8): packed
    // `SPEC_MAJOR * 16 + SPEC_MINOR`, each < 16. Derived rather than written out so
    // the two cannot drift the way they did between the 0.6 and 0.7 lines.
    uint8 private constant SPEC_MAJOR = 0;
    uint8 private constant SPEC_MINOR = 7;
    uint8 private constant CONTRACT_VERSION = SPEC_MAJOR * 16 + SPEC_MINOR;

    struct ProofRecord {
        string proofId;
        uint8 contractVersion;
        string prover;
        string passportId;
        bytes32 documentHash; // SHA-256 of the signed expertise document; bytes32(0) = none
        string documentUrl;
        uint256 timestamp;
    }

    mapping(uint32 => mapping(uint32 => bool)) private _proofNumberTaken;
    mapping(string => ProofRecord) private _proofs;
    mapping(string => string[]) private _passportProofs;
    mapping(string => string[]) private _institutionProofs;
    struct Operation { bytes32 digest; string proofId; }
    mapping(address => mapping(bytes32 => Operation)) public proofOperations;
    error InvalidProofOperation();
    error ProofAlreadyCommitted(bytes32 operationId, string proofId);
    error ProofOperationConflict(bytes32 operationId);
    event ProofOperationCommitted(address indexed author, bytes32 indexed operationId, string proofId, bytes32 digest);
    uint256 private _proofNonce;
    mapping(string => address) public proofAuthor;
    mapping(string => uint256) public proofWithdrawnAt;
    mapping(string => bytes32) public proofWithdrawalReason;
    event ProofWithdrawn(string indexed proofId, string proofIdText, address indexed author, bytes32 reasonHash, uint256 timestamp);
    error InvalidProofWithdrawal();

    function withdrawProof(string calldata proofId, bytes32 reasonHash) external {
        if (proofAuthor[proofId] != msg.sender || proofWithdrawnAt[proofId] != 0 || reasonHash == bytes32(0)) revert InvalidProofWithdrawal();
        proofWithdrawnAt[proofId] = block.timestamp;
        proofWithdrawalReason[proofId] = reasonHash;
        emit ProofWithdrawn(proofId, proofId, msg.sender, reasonHash, block.timestamp);
    }

    event ProofSubmitted(
        string indexed proofId,
        string indexed passportId,
        string indexed prover,
        string proofIdText,
        string passportIdText,
        string proverText,
        uint256 timestamp
    );

    constructor(address registry_) ODPSatellite(registry_) {
    }

    function submitProof(
        string calldata passportId,
        bytes32 documentHash,
        string calldata documentUrl,
        uint32 year,
        uint8 month,
        bytes32 operationId
    ) external returns (string memory proofId) {
        if (operationId == bytes32(0)) revert InvalidProofOperation();
        bytes32 digest = keccak256(abi.encode("ODP-PROOF-OPERATION-0.7", block.chainid,
            address(odpRegistry), address(this), msg.sender, passportId, documentHash, documentUrl, year, month));
        Operation storage operation = proofOperations[msg.sender][operationId];
        if (bytes(operation.proofId).length != 0) {
            if (operation.digest != digest) revert ProofOperationConflict(operationId);
            revert ProofAlreadyCommitted(operationId, operation.proofId);
        }
        IODPRegistry.PassportClassificationView memory classification = odpRegistry.getPassportClassification(passportId);
        if (classification.revoked) revert EC(11);
        if (!(bytes(documentUrl).length <= 512)) revert EC(10);
        if (!(year > 0)) revert EC(9);
        if (!(month >= 1 && month <= 12)) revert EC(8);
        _requireUtcYearMonth(year, month);

        string memory callerId = _institution();

        if (documentHash == bytes32(0)) {
            if (!(bytes(documentUrl).length == 0)) revert EC(5);
        }

        proofId = _generateProofId(year, month, passportId);

        _proofs[proofId] = ProofRecord({
            proofId: proofId,
            contractVersion: CONTRACT_VERSION,
            prover: callerId,
            passportId: passportId,
            documentHash: documentHash,
            documentUrl: documentUrl,
            timestamp: block.timestamp
        });

        proofAuthor[proofId] = msg.sender;
        _passportProofs[passportId].push(proofId);
        _institutionProofs[callerId].push(proofId);

        operation.digest = digest;
        operation.proofId = proofId;
        emit ProofOperationCommitted(msg.sender, operationId, proofId, digest);
        emit ProofSubmitted(proofId, passportId, callerId, proofId, passportId, callerId, block.timestamp);
    }

    function getProof(string calldata proofId)
        external
        view
        returns (ProofRecord memory)
    {
        if (!(bytes(_proofs[proofId].proofId).length > 0)) revert EC(4);
        return _proofs[proofId];
    }

    function _requireUtcYearMonth(uint32 year, uint8 month) private view {
        (uint32 cy, uint8 cm) = ODPPassportLib.utcYearMonthFromTimestamp(block.timestamp);
        if (!(year == cy && month == cm)) revert EC(68);
    }

    function _generateProofId(uint32 year, uint8 month, string memory passportId)
        internal
        returns (string memory)
    {
        uint32 key = uint32(year) * 100 + uint32(month);
        uint256 baseNonce = _proofNonce;
        bytes32 passportIdHash = keccak256(bytes(passportId));
        for (uint256 i = 0; i < 25; i++) {
            // Human-readable PRF ID entropy, not security randomness (mirrors main registry triage).
            // slither-disable-next-line weak-prng
            uint32 n = uint32(uint256(keccak256(abi.encodePacked(
                block.timestamp,
                block.prevrandao,
                msg.sender,
                baseNonce + i,
                key,
                passportIdHash,
                gasleft()
            ))) % 100_000_000);
            if (!_proofNumberTaken[key][n]) {
                _proofNonce = baseNonce + i + 1;
                _proofNumberTaken[key][n] = true;
                return ODPPassportLib.formatPrfId(year, month, n);
            }
        }
        revert EC(60);
    }
    function getProofsForPassportPaged(string calldata id, uint256 offset, uint256 limit)
        external view returns (string[] memory, uint256) { return _page(_passportProofs[id], offset, limit); }
    function getProofsByInstitutionPaged(string calldata id, uint256 offset, uint256 limit)
        external view returns (string[] memory, uint256) { return _page(_institutionProofs[id], offset, limit); }
}

ODPPassportTypes.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @dev Spec 0.7 immutable on-chain card + classification captured at mint.
struct PassportCoreMintInputs {
    uint32 year;
    uint8 month;
    string title;            // 1..128 bytes; must match passport.json byte-for-byte
    string authorName;       // 1..128 bytes; must match passport.json byte-for-byte
    string shortDescription; // 1..256 bytes; must match passport.json byte-for-byte
    string domain;           // <=128 bytes; must match passport.json byte-for-byte
    uint8 contentClass;
    uint8 lifecycleStatus;
    uint8 aiStatus;
    uint8 verificationMethod;
    uint8 editionModel;
}

/// @dev Spec 0.7 unified mint tuple for physical / digital / mixed entrypoints.
///      `fileHash` must be bytes32(0) for physical and non-zero for digital/mixed.
struct PassportMintInputs {
    PassportCoreMintInputs core;
    bytes32 dataHash;        // SHA-256 of canonical minified passport.json
    bytes32 imageHash;       // SHA-256 of the primary photo; required for physical/mixed
    bytes32 fileHash;        // SHA-256 of the digital original
    bytes32 anchorsHash;     // SHA-256 of the canonical minified `anchors` array
    uint32 anchorTypesMask;  // OR of anchor type bits (see ODPAnchorBits)
    bytes32 editionCommitment; // Typed edition commitment; zero iff UNIT_KEY_SET is absent.
}

/// @dev Anchor type bits for `anchorTypesMask`. Bits 14..30 reserved for future SPEC
///      revisions; bit 31 marks a custom anchor outside the registry.
library ODPAnchorBits {
    uint32 internal constant PHOTO = 1;
    uint32 internal constant DIMENSIONS = 2;
    uint32 internal constant MATERIALS = 4;
    uint32 internal constant DISTINGUISHING_FEATURES = 8;
    uint32 internal constant MARKS = 16;
    uint32 internal constant FILE_HASH = 32;
    uint32 internal constant PERCEPTUAL_HASH = 64;
    uint32 internal constant C2PA = 128;
    uint32 internal constant NFC = 256;
    uint32 internal constant NUMBERED_SEAL = 512;
    uint32 internal constant FINGERPRINT = 1024;
    uint32 internal constant DNA = 2048;
    uint32 internal constant UNIT_KEY_SET = 4096;        // SPEC 0.7 §20.3 (B profiles only)
    uint32 internal constant UNIT_VARIANT_COMMIT = 8192; // SPEC 0.7 §20.4 (B profiles only)
    uint32 internal constant CUSTOM = 1 << 31;

    /// Hard identification minimum: photo + dimensions + materials + distinguishing features.
    uint32 internal constant PHYSICAL_REQUIRED = PHOTO | DIMENSIONS | MATERIALS | DISTINGUISHING_FEATURES;
    uint32 internal constant DIGITAL_REQUIRED = FILE_HASH;
}

